<script setup lang="ts">
import { ref,computed,watch } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import { request,uuid } from '../../api'
import { work,resources,personal,requireWorkspace,loadWorkspace,goCase,goHome,navigate,localDay,dayLabel,clock,money,doctorName,clinicName,queryString,type Row } from '../../workspace'
const doctorProfile=ref<Row|null>(null)
const phaseDefinition=ref<Row|null>(null),slotPeriod=ref('上午')
const step=ref(1),busy=ref(false),loadingOptions=ref(false),error=ref(''),options=ref<any>(null),slots=ref<Row[]>([]),selectedSlot=ref<Row|null>(null),result=ref<Row|null>(null)
const patientId=ref<number|undefined>(),clinicId=ref<number|undefined>(),date=ref(''),standardIds=ref<number[]>([]),doctorId=ref<number|undefined>(),requestText=ref(''),specialNeeds=ref(''),mode=ref('project'),reason=ref('')
const original=ref<Row|null>(null),originalId=ref(0),phaseId=ref(0),ready=ref(false)
let optionsGeneration=0,lastPayload='',pendingKey=''
let preferredClinic=0, preferredDate=''
const preferredDoctor=ref<number|undefined>()
onLoad((query:any)=>{originalId.value=Number(query?.appointment||0);phaseId.value=Number(query?.phase||0);preferredClinic=Number(query?.clinic||0);preferredDate=String(query?.day||'');preferredDoctor.value=Number(query?.dentist||0)||undefined})
onShow(async()=>{if(ready.value)return;const ws=await requireWorkspace(originalId.value?'UC03':'UC02');if(!ws)return;patientId.value=ws.resources.patients?.[0]?.id
 if(originalId.value){try{const detail=await request('/api/appointments/'+originalId.value);original.value=detail.appointment;if(detail.phases?.length===1)phaseId.value=detail.phases[0].id;patientId.value=original.value?.patient_id;clinicId.value=original.value?.clinic_id;requestText.value=original.value?.presenting_request||''}catch(e:any){error.value=e.message}}
 if(phaseId.value){const phase=resources.value.phases?.find(p=>p.id===phaseId.value);if(phase){patientId.value=phase.patient_id;clinicId.value=phase.responsible_clinic_id}}
 if(phaseId.value&&patientId.value){try{const journey=await request('/api/patient-journey?patient_id='+patientId.value);phaseDefinition.value=journey.plans.flatMap((p:Row)=>p.phases).find((p:Row)=>p.id===phaseId.value)||null;if(!phaseDefinition.value?.can_book&&!(originalId.value&&phaseDefinition.value?.appointment?.id===originalId.value&&phaseDefinition.value?.progress_outcome==='booked'))error.value='此阶段当前不可预约，请返回治疗接续核对状态。'}catch(e:any){error.value=e.message}}
 if(!originalId.value&&!phaseId.value&&ws.resources.clinics?.some(c=>c.id===preferredClinic)){
  clinicId.value=preferredClinic
  if(/^\d{4}-\d{2}-\d{2}$/.test(preferredDate)&&preferredDate>=localDay())date.value=preferredDate
 }
 ready.value=true;if(clinicId.value)fetchOptions()
})
const patient=computed(()=>resources.value.patients?.find(p=>p.id===patientId.value))
const clinic=computed(()=>resources.value.clinics?.find(c=>c.id===clinicId.value))
const selectedStandards=computed(()=>(options.value?.standards||[]).filter((s:Row)=>standardIds.value.includes(s.id)))
const exam=computed(()=>(options.value?.standards||[]).find((s:Row)=>/初步检查|初诊检查|口腔检查/.test(s.treatment_name)))
const estimatedMinutes=computed(()=>Math.ceil(selectedStandards.value.reduce((n:number,s:Row)=>n+s.duration_minutes*(phaseDefinition.value?phaseDefinition.value.items.filter((i:Row)=>i.standard_id===s.id).reduce((total:number,i:Row)=>total+Number(i.planned_quantity),0):1),0)))
const estimatedFee=computed(()=>selectedStandards.value.reduce((n:number,s:Row)=>n+Number(s.unit_price)*(phaseDefinition.value?phaseDefinition.value.items.filter((i:Row)=>i.standard_id===s.id).reduce((total:number,i:Row)=>total+Number(i.planned_quantity),0):1),0))
const visibleSlots=computed(()=>slots.value.filter(s=>!doctorId.value||s.dentist_id===doctorId.value))
const uniqueSlots=computed(()=>{const seen=new Set<string>();return visibleSlots.value.filter(s=>{const key=s.dentist_id+'-'+s.starts_at+'-'+s.ends_at;if(seen.has(key))return false;seen.add(key);return true})})
const availableDoctors=computed(()=>{const ids=new Set(slots.value.map(s=>s.dentist_id));return (options.value?.doctors||[]).filter((d:Row)=>ids.has(d.id))})
const sessions=computed(()=>[{name:'上午',rows:uniqueSlots.value.filter(s=>Number(clock(s.starts_at).slice(0,2))<12)},{name:'下午及其他时段',rows:uniqueSlots.value.filter(s=>Number(clock(s.starts_at).slice(0,2))>=12)}].filter(s=>s.rows.length))
const extraDetails=ref(false),showAllProjects=ref(false)
const projectLimit=3
const projectChoices=computed<Row[]>(()=>options.value?.standards||[])
const shownProjects=computed(()=>showAllProjects.value||phaseDefinition.value
 ?projectChoices.value
 :projectChoices.value.filter((project,index)=>index<projectLimit||standardIds.value.includes(project.id)))
const channel=computed(()=>work.data?.scope.role_code==='patient'?'本人自助':work.data?.scope.role_code==='representative'?'授权代办':'前台或门店协助')
watch([clinicId,date],()=>{slots.value=[];selectedSlot.value=null;doctorId.value=undefined;if(ready.value&&clinicId.value)fetchOptions()})
watch([patientId,standardIds,phaseId],()=>{slots.value=[];selectedSlot.value=null;doctorId.value=undefined},{deep:true})
watch(mode,value=>{standardIds.value=value==='symptom'&&exam.value?[exam.value.id]:[];selectedSlot.value=null})
async function fetchOptions(){const epoch=++optionsGeneration;loadingOptions.value=true;error.value='';try{const query=queryString({clinic_id:String(clinicId.value),patient_id:String(patientId.value||''),date:date.value||localDay(),assets:'network',...(originalId.value?{appointment_id:String(originalId.value)}:{})});const response=await request('/api/booking/options?'+query);if(epoch!==optionsGeneration)return;options.value=response;if(phaseDefinition.value)standardIds.value=[...new Set<number>(phaseDefinition.value.items.map((i:Row)=>Number(i.standard_id)))];standardIds.value=standardIds.value.filter(id=>response.standards.some((s:Row)=>s.id===id));if(mode.value==='symptom'&&exam.value)standardIds.value=[exam.value.id]}catch(e:any){if(epoch===optionsGeneration)error.value=e.message}finally{if(epoch===optionsGeneration)loadingOptions.value=false}}
function goDirectory(){navigate('/pages/directory/index')}
function chooseClinic(id:number){if(clinicId.value===id)return;preferredDoctor.value=undefined;clinicId.value=id;date.value='';options.value=null;standardIds.value=[]}
function chooseProject(id:number){if(phaseDefinition.value)return;standardIds.value=standardIds.value.includes(id)?standardIds.value.filter(x=>x!==id):[...standardIds.value,id]}
function selectPatient(e:any){patientId.value=resources.value.patients?.[Number(e.detail.value)]?.id;if(clinicId.value)fetchOptions()}
function otherDate(e:any){date.value=e.detail.value}
async function search(){error.value='';if(!patientId.value||!clinicId.value||!date.value){error.value='请先选好就诊人、门店和已发布出诊的日期。';return}if(!options.value?.days.includes(date.value)){error.value='所选日期没有已确认营业和已发布出诊，请选择列出的日期。';return}if(phaseDefinition.value&&phaseDefinition.value.items.some((i:Row)=>!standardIds.value.includes(i.standard_id))){error.value='此阶段的项目标准已变化，请联系牙医核对已确认方案。';return}if(mode.value==='project'&&!standardIds.value.length&&!phaseDefinition.value){error.value='请选择拟治疗项目，或改为描述症状后安排初步检查。';return}if(mode.value==='symptom'&&!requestText.value.trim()){error.value='请简要描述症状或就诊诉求，无需自行判断诊断。';return}if(original.value&&!reason.value.trim()){error.value='请填写本次改期原因。';return}busy.value=true;try{const query=queryString({clinic_id:String(clinicId.value),patient_id:String(patientId.value),date:date.value,standard_ids:standardIds.value.join(','),minutes:String(estimatedMinutes.value||30),presenting_request:requestText.value||(phaseDefinition.value?'接续已确认阶段：'+phaseDefinition.value.phase_title:'按所选项目安排'),...(phaseId.value?{phase_id:String(phaseId.value)}:{}),...(originalId.value?{appointment_id:String(originalId.value)}:{})});slots.value=(await request('/api/slots?'+query)).slots;doctorId.value=slots.value.some(s=>s.dentist_id===preferredDoctor.value)?preferredDoctor.value:undefined;slotPeriod.value=sessions.value[0]?.name||'上午';step.value=2;if(!slots.value.length)error.value='该日暂无满足项目资质及完整时长的可约安排。请保留诉求，调整日期、门店或项目。';uni.pageScrollTo({scrollTop:0,duration:0})}catch(e:any){error.value=e.message}finally{busy.value=false}}
function review(){if(!selectedSlot.value){error.value='请选择一个医生、患者和诊疗位同时可用的完整时段。';return}error.value='';step.value=3;uni.pageScrollTo({scrollTop:0,duration:0})}
async function confirm(){if(!selectedSlot.value)return;busy.value=true;error.value='';const target={...selectedSlot.value,patient_id:patientId.value,standard_ids:standardIds.value,presenting_request:requestText.value||(phaseDefinition.value?'接续已确认阶段：'+phaseDefinition.value.phase_title:'按所选项目安排'),special_needs:specialNeeds.value,...(phaseId.value?{phase_id:phaseId.value}:{})};const payload=original.value?{action:'reschedule',id:original.value.id,row_version:original.value.row_version,reason:reason.value,replacement:target}:{action:'book',...target};const raw=JSON.stringify(payload);if(lastPayload!==raw){pendingKey=uuid();lastPayload=raw}try{result.value=await request('/api/use-cases/'+(original.value?'UC03':'UC02'),payload,pendingKey);if(result.value?.replayed){const saved=await request('/api/appointments/'+result.value.id);result.value={...saved.appointment,replayed:true}}pendingKey='';lastPayload='';await loadWorkspace(true);step.value=4;uni.pageScrollTo({scrollTop:0,duration:0})}catch(e:any){error.value=e.message;if(e.status===409){step.value=2;selectedSlot.value=null}}finally{busy.value=false}}
function copyReceipt(){
 if(result.value?.appointment_no)uni.setClipboardData({data:result.value.appointment_no})
}
</script>
<template>
 <WorkspaceShell :title="original?'改期与重新安排':personal?'预约就诊':'安排患者预约'" :active="original?'UC03':'UC02'" back hide-footer>
  <view class="booking-page"><view v-if="step<4" class="booking-progress"><view v-for="(label,i) in ['就诊安排','医生与时段','核对确认']" :key="label" class="progress-step" :class="{current:step===i+1,done:step>i+1}"><text class="progress-number">{{i+1}}</text><text>{{label}}</text></view></view>
  <view v-if="error" class="error booking-error">{{error}}</view>
  <view v-if="step===1" class="booking-columns"><view class="booking-main">
   <view class="booking-section"><view class="booking-section-title"><text>就诊人</text></view><picker :range="resources.patients||[]" range-key="full_name" :disabled="!!original" @change="selectPatient"><view class="patient-selector"><view class="patient-symbol"><AppIcon name="person" :size="24"/></view><view><text class="selector-title">{{patient?.full_name||'选择就诊人'}}</text><text class="supporting">{{patient?.account_no||'由门店核实身份后开通'}}</text></view><AppIcon v-if="!original" name="down" :size="17" color="#758296"/></view></picker></view>
   <view class="booking-section"><view class="booking-section-title"><text>就诊门店</text><button v-if="personal&&!original&&!phaseDefinition" class="text-button" @click="goDirectory">查看门店与医生</button></view><view class="clinic-options"><button v-for="c in resources.clinics" :key="c.id" class="clinic-option" :class="{selected:clinicId===c.id}" @click="chooseClinic(c.id)"><view class="clinic-option-top"><AppIcon name="location" :size="22"/><text>{{c.clinic_name}}</text><AppIcon :name="clinicId===c.id?'checkbox-filled':'circle'" :size="20" :color="clinicId===c.id?'#3278cf':'#758296'"/></view><text class="supporting">{{c.postal_address}}</text></button></view></view>
   <view v-if="clinicId" class="booking-section"><view class="booking-section-title"><text>就诊日期</text><picker mode="date" :start="localDay()" :value="date||localDay()" @change="otherDate"><button class="text-button">其他日期 <AppIcon name="calendar" :size="16"/></button></picker></view><text v-if="loadingOptions" class="supporting">正在读取门店日历与已发布出诊…</text><scroll-view v-else scroll-x class="date-scroll"><view class="date-options"><button v-for="day in options?.days||[]" :key="day" class="date-option" :class="{selected:date===day}" @click="date=day"><text>{{dayLabel(day).split('日')[1]||'已排班'}}</text><text class="date-day">{{Number(day.slice(-2))}}</text><text>{{Number(day.slice(5,7))}}月</text></button></view></scroll-view><view v-if="!loadingOptions&&!options?.days?.length" class="inline-empty">该时间范围暂无已发布出诊，请更换门店或联系门店。已填写的诉求会保留。</view><text class="supporting date-caption">列出的日期已有确认营业及发布出诊，具体号源以查询结果为准。</text></view>
   <view v-if="clinicId" class="booking-section"><view class="booking-section-title"><text>{{phaseDefinition?phaseDefinition.phase_title:'就诊项目'}}</text><text v-if="phaseDefinition" class="required-note">按已确认阶段安排，保留项目及先决条件</text></view><view v-if="!phaseDefinition" class="booking-modes"><button :class="{selected:mode==='project'}" @click="mode='project'">选择项目</button><button :class="{selected:mode==='symptom'}" @click="mode='symptom'">先做初步检查</button></view><view v-if="mode==='project'" class="project-options"><button v-for="s in shownProjects" :key="s.id" class="project-option" :class="{selected:standardIds.includes(s.id)}" @click="chooseProject(s.id)"><view><text class="project-title">{{s.treatment_name}}</text><text class="supporting">预计 {{s.duration_minutes}} 分钟 · {{s.unit_name}}</text></view><view><text class="project-price">¥{{money(s.unit_price)}}</text><AppIcon :name="standardIds.includes(s.id)?'checkbox-filled':'circle'" :size="20" :color="standardIds.includes(s.id)?'#3278cf':'#758296'"/></view></button></view><view v-else class="examination-note"><AppIcon name="info" :size="21"/><text>无法确定项目时，描述你的就诊诉求。系统按有效的初步检查标准安排，实际治疗由牙医检查、说明后确认。</text></view><button v-if="mode==='project'&&!phaseDefinition&&projectChoices.length>projectLimit" class="text-button more-projects" :aria-expanded="showAllProjects" @click="showAllProjects=!showAllProjects">{{showAllProjects?'收起其他项目':'查看全部项目（'+projectChoices.length+'项）'}} <AppIcon :name="showAllProjects?'up':'down'" :size="14"/></button><view v-if="mode==='symptom'||extraDetails" class="booking-field"><text class="label">症状或就诊诉求{{mode==='symptom'?'（必填）':'（选填）'}}</text><textarea class="input" v-model="requestText" aria-label="症状或就诊诉求" placeholder="简要填写这次想咨询的问题"/></view><button class="text-button more-details" @click="extraDetails=!extraDetails">{{extraDetails?'收起选填信息':'补充就诊说明（选填）'}} <AppIcon :name="extraDetails?'up':'down'" :size="14"/></button><view v-if="extraDetails" class="booking-field"><text class="label">特殊需要或注意事项（选填）</text><textarea class="input" v-model="specialNeeds" aria-label="特殊需要或注意事项" placeholder="填写希望门店提前了解的事项"/></view><view v-if="original" class="booking-field"><text class="label">改期原因</text><textarea class="input" v-model="reason" aria-label="改期原因" placeholder="原预约与本次变更原因会保留"/></view></view>
  </view><view class="booking-aside"><view class="booking-summary"><text class="summary-title">本次就诊安排</text><view class="summary-line"><text>就诊人</text><text>{{patient?.full_name||'待选择'}}</text></view><view class="summary-line"><text>门店</text><text>{{clinic?.clinic_name||'待选择'}}</text></view><view class="summary-line"><text>日期</text><text>{{date||'待选择'}}</text></view><view class="summary-line"><text>拟治疗</text><text>{{selectedStandards.map((s:Row)=>s.treatment_name).join('、')||'待选择'}}</text></view><view class="summary-line"><text>预计时长</text><text>{{estimatedMinutes?estimatedMinutes+'分钟':mode==='symptom'||phaseDefinition?'初步检查或复查约30分钟':'由有效项目标准确定'}}</text></view><view class="fee-estimate"><text>{{selectedStandards.length?'项目参考合计':'实际项目与费用'}}</text><text>{{selectedStandards.length?'¥'+money(estimatedFee):'检查后据实确定'}}</text></view><text class="supporting">{{selectedStandards.length?'参考金额用于理解拟安排项目，实际结算依已签署的实施数量和价格依据形成。':'先安排30分钟初步检查；实际治疗项目与费用由牙医说明并根据实施情况确认。'}}</text></view><view class="booking-principle"><AppIcon name="locked" :size="23"/><text>确认时再次核验</text><text class="supporting">门店营业、医生出诊、有效资格，以及医生、患者和诊疗位的完整时段占用。</text></view></view></view>
  <view v-if="step===2" class="time-selection"><view class="selected-arrangement"><text class="focus-name">{{clinic?.clinic_name}}</text><text>{{patient?.full_name}} · {{dayLabel(date)}} · 预计 {{estimatedMinutes}} 分钟</text><button class="text-button" @click="step=1">修改就诊安排</button></view><view class="booking-section"><view class="booking-section-title"><text>选择接诊医生</text><text class="required-note">只展示本次有可行时段的医生</text></view><view class="doctor-preference"><button class="text-button" @click="doctorId=undefined;selectedSlot=null">{{doctorId?'查看全部可约医生':'全部可约医生'}} <AppIcon v-if="!doctorId" name="checkmarkempty" :size="16"/></button><text class="supporting">教学医生资料为示意</text></view><view class="doctor-options"><view v-for="d in availableDoctors" :key="d.id" class="doctor-option" :class="{'doctor-selected':doctorId===d.id}"><image v-if="d.photo" class="doctor-photo" :src="d.photo" mode="aspectFill" :aria-label="d.full_name+'的教学医生照片'"/><view v-else class="doctor-photo doctor-photo-empty"><AppIcon name="person" :size="32" color="#758296"/><text>暂无照片</text></view><view class="doctor-card-body"><view class="doctor-name-line"><text class="doctor-name">{{d.full_name}}</text><text class="doctor-category">牙医</text><AppIcon v-if="doctorId===d.id" name="checkbox-filled" :size="19"/></view><text class="doctor-qualifications">{{d.qualifications.join(' · ')||'本次项目资格按时点核验'}}</text><text class="doctor-introduction">{{d.introduction}}</text><view class="doctor-actions"><button class="text-button" @click="doctorProfile=d">查看医生资料 <AppIcon name="right" :size="12"/></button><button class="doctor-select" :class="{primary:doctorId===d.id}" @click="doctorId=d.id;selectedSlot=null">{{doctorId===d.id?'已选这位医生':'选这位医生'}}</button></view></view></view></view></view><view v-if="sessions.length" class="time-period-tabs"><button v-for="period in sessions" :key="period.name" :class="{selected:slotPeriod===period.name}" @click="slotPeriod=period.name">{{period.name}} <text>{{period.rows.length}} 个可选安排</text></button></view><view v-for="period in sessions.filter(p=>p.name===slotPeriod)" :key="period.name" class="booking-section"><view class="booking-section-title"><text>{{period.name}}</text><text class="required-note">选择一个时段</text></view><scroll-view scroll-y class="slots-viewport"><view class="time-options"><button v-for="s in period.rows" :key="s.dentist_id+'-'+s.starts_at" class="time-option" :class="{selected:selectedSlot===s}" @click="selectedSlot=s"><text class="time-range">{{clock(s.starts_at)}}—{{clock(s.ends_at)}}</text><text class="supporting">{{doctorName(s.dentist_id)}} · 诊疗位 {{s.operatory_id}}</text></button></view></scroll-view></view><view v-if="!slots.length" class="no-slots"><AppIcon name="calendar" :size="38" color="#758296"/><text>暂无符合条件的完整时段</text><text class="supporting">可以更换门店、日期或项目；接续阶段的先决条件由牙医确认。</text><button @click="step=1">调整就诊安排</button></view></view>
  <view v-if="step===3&&selectedSlot" class="confirmation"><view class="confirmation-heading"><view class="confirmation-symbol"><AppIcon name="checkbox" :size="34"/></view><text class="confirmation-title">请核对这次就诊安排</text><text class="supporting">确认后固定具体门店、牙医、诊疗位与完整时段</text></view><view class="confirmation-sheet"><view class="confirmation-clinic"><AppIcon name="location" :size="26"/><view><text>{{clinic?.clinic_name}}</text><text class="supporting">{{clinic?.postal_address}} · {{clinic?.phone}}</text></view></view><view class="confirmation-grid"><view><text>就诊人</text><text>{{patient?.full_name}}</text></view><view><text>办理方式</text><text>{{channel}}</text></view><view><text>接诊牙医</text><text>{{doctorName(selectedSlot.dentist_id)}}</text></view><view><text>诊疗资源</text><text>诊疗位 {{selectedSlot.operatory_id}}</text></view><view class="full-span"><text>完整时段</text><text>{{dayLabel(selectedSlot.starts_at)}} {{clock(selectedSlot.starts_at)}}—{{clock(selectedSlot.ends_at)}}</text></view><view class="full-span"><text>拟治疗项目</text><text>{{selectedStandards.map((s:Row)=>s.treatment_name).join('、')||(phaseDefinition?'按已确认阶段安排复查':'先做初步检查')}}</text></view><view class="full-span"><text>{{selectedStandards.length?'项目参考金额':'实际项目与费用'}}</text><text>{{selectedStandards.length?'¥'+money(estimatedFee)+'，实际结算依签署的实施记录形成':'检查后据实确定'}}</text></view><view v-if="requestText" class="full-span"><text>就诊诉求</text><text>{{requestText}}</text></view></view><view v-if="original" class="change-reminder">新安排保存成功时才释放原预约；本次变更失败会保留原约。</view><text class="confirmation-footnote">本次为预约安排。实际实施及同意由牙医核实，结算依据已签署的实际治疗。</text></view></view>
  <view v-if="step===4&&result" class="booking-result"><view class="result-icon"><AppIcon name="checkmarkempty" :size="42" color="#ffffff"/></view><text class="result-title">{{original?'新安排已确认':'预约已确认'}}</text><text class="supporting">{{result.replayed?'已返回本次请求原有结果，未重复预约。':'本次安排已保存，门店与医生可读取同一份记录。'}}</text><view class="result-sheet"><text class="result-clinic">{{clinicName(result.clinic_id)}}</text><text class="result-time">{{dayLabel(result.starts_at)}} {{clock(result.starts_at)}}—{{clock(result.ends_at)}}</text><view class="result-line"><text>{{patient?.full_name}} · {{doctorName(result.dentist_id)}}</text><text>诊疗位 {{result.operatory_id}}</text></view><text class="result-number">预约编号 {{result.appointment_no}}</text></view><view class="result-notes"><AppIcon name="info" :size="21"/><text>预约当天实际到店后，可在“我的预约”办理报到；改期、取消和阶段接续也保留在同一记录中。</text></view><view class="result-actions"><button class="quiet copy-receipt" @click="copyReceipt">复制预约号</button><button class="primary" @click="goCase('UC03',{id:result.id})">查看我的预约</button><button @click="goHome">返回首页</button></view></view>
