  <view v-if="step<4" class="booking-bottom"><view class="booking-bottom-note"><text>{{step===1?'下一步选择医生与时段':step===2&&selectedSlot?doctorName(selectedSlot.dentist_id)+' · '+clock(selectedSlot.starts_at)+'—'+clock(selectedSlot.ends_at):step===3?'保存时再次核验排班、资格和资源':'请选择一个可行时段'}}</text><text v-if="step===1&&estimatedMinutes" class="supporting">预计 {{estimatedMinutes}} 分钟 · 参考 ¥{{money(estimatedFee)}}</text></view><view class="booking-bottom-actions"><button v-if="step>1" @click="step--;error=''">上一步</button><button class="primary submit-button" :disabled="busy||loadingOptions" @click="step===1?search():step===2?review():confirm()">{{busy?'办理中…':step===1?'查看可约时段':step===2?'核对预约信息':original?'确认改期':'确认预约'}}</button></view></view>
  </view>
